import { DraggableNode } from './draggableNode';
import { LogIn, BrainCircuit, LogOut, Type, Filter, Wand2, Merge, StickyNote, Globe } from 'lucide-react';

const NODE_DEFS = [
  { type: 'customInput',  label: 'Input',     color: '#6366f1', Icon: LogIn },
  { type: 'llm',          label: 'LLM',       color: '#10b981', Icon: BrainCircuit },
  { type: 'customOutput', label: 'Output',    color: '#ec4899', Icon: LogOut },
  { type: 'text',         label: 'Text',      color: '#f59e0b', Icon: Type },
  { type: 'filter',       label: 'Filter',    color: '#06b6d4', Icon: Filter },
  { type: 'transform',    label: 'Transform', color: '#a855f7', Icon: Wand2 },
  { type: 'merge',        label: 'Merge',     color: '#eab308', Icon: Merge },
  { type: 'note',         label: 'Note',      color: '#64748b', Icon: StickyNote },
  { type: 'api',          label: 'API',       color: '#14b8a6', Icon: Globe },
];

export const PipelineToolbar = () => (
  <div style={{
    padding: '0 20px',
    height: 56,
    background: '#111118',
    borderBottom: '1px solid #1e1e2a',
    display: 'flex',
    alignItems: 'center',
    gap: 6,
    overflowX: 'auto',
    flexShrink: 0,
  }}>
    <span style={{
      fontSize: 10,
      fontWeight: 700,
      color: '#2a2a3a',
      letterSpacing: 1.5,
      textTransform: 'uppercase',
      marginRight: 8,
      flexShrink: 0,
    }}>
      Nodes
    </span>
    {NODE_DEFS.map(n => (
      <DraggableNode key={n.type} type={n.type} label={n.label} color={n.color} Icon={n.Icon} />
    ))}
  </div>
);
